insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$pato-branco$q$, $q$https://www.diariomunicipal.com.br/amp/materia/814EED8A (Decreto 10.412/2025, Diário Oficial dos Municípios do Paraná)$q$, $q$Ato oficial de Pato Branco: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 44, $q$Decreto 10.412/2025 (revoga o 10.374/2025); alterado pelo Decreto 10.730/2025 só quanto ao art. 21-A (suspensão da cobrança do ESTAR), sem tocar o art. 17 §4º. O §4º não fixa horário (aplicado 24 h). Pato Branco não define VUC nos atos lidos. Decreto 8.260/2018 (estradas do interior) fica desativado por redação ambígua.$q$);
